mapper.select:
     	select deadline1.*
     	from(select rownum num, deadline.* from(
	       SELECT
		  A.BUSI_DATE busiDate,
		  A.MARKET_CODE marketCode,
		  A.IS_HOLIDAY isHoliday
		 FROM CHB_MKT_HOLIDAY A


	           	A.BUSI_DATE < to_date(#{holidayDate},'yyyy-MM-dd')


	           	A.BUSI_DATE > to_date(#{holidayDate},'yyyy-MM-dd')

		 	AND A.MARKET_CODE = #{marketCode,jdbcType=VARCHAR}
		 	AND A.IS_HOLIDAY = '0'


	           	order by A.BUSI_DATE desc


	           	order by A.BUSI_DATE asc

		 )deadline
		 )deadline1
		 where deadline1.num = #{days,jdbcType=INTEGER}

        SELECT DISTINCT LARGE_SH_DATE
		FROM REP_PROD_INFO_TA
		WHERE IS_LARGE_SH='1'
		AND LARGE_SH_DATE= #{sysDate, jdbcType=DATE}
		AND PROD_ID = #{prodId, jdbcType=VARCHAR}

  		 select 

			 DPP.OPEN_END_DATE


			 DPP.OPEN_START_DATE


			 DPP.OPERATION_START_DATE

	     from DIS_PROD_PLAN DPP
		inner join REP_PROD_INFO RPI on DPP.PROD_ID=RPI.P_PROD_ID
	     where RPI.PROD_ID = #{prodId, jdbcType=VARCHAR}
	     AND DPP.DATA_STATUS = 'E'

	     	AND DPP.OPEN_END_DATE = #{sysDate, jdbcType=DATE}


	        AND DPP.OPEN_START_DATE = #{sysDate, jdbcType=DATE}


	        AND DPP.OPERATION_START_DATE = #{sysDate, jdbcType=DATE}

     	select deadline1.*
     	from(select rownum num, deadline.* from(
	       SELECT
		  A.BUSI_DATE busiDate,
		  A.MARKET_CODE marketCode,
		  A.IS_HOLIDAY isHoliday
		 FROM CHB_MKT_HOLIDAY A


	           	A.BUSI_DATE > to_date(#{holidayDate},'yyyy-MM-dd')


	           	A.BUSI_DATE < to_date(#{holidayDate},'yyyy-MM-dd')

		 	AND A.MARKET_CODE = #{marketCode,jdbcType=VARCHAR}
		 	AND A.IS_HOLIDAY = '0'


	           	order by A.BUSI_DATE asc


	           	order by A.BUSI_DATE desc

		 )deadline
		 )deadline1
		 where deadline1.num = #{days,jdbcType=INTEGER}

SELECT DISTINCT T.SETT_DATE
FROM DIS_PROD_BONUSPLAN T
WHERE
	BONUS_MODE='01'
  AND SETT_DATE = #{sysDate, jdbcType=DATE}
  AND PROD_ID= #{prodId, jdbcType=VARCHAR}

SELECT DISTINCT T.AUTO_REDEEM_DATE
FROM DIS_PROD_PLAN T
WHERE
	1=1
  AND AUTO_REDEEM_DATE = #{sysDate, jdbcType=DATE}
  AND PROD_ID= #{prodId, jdbcType=VARCHAR}
  AND EXISTS(
		SELECT 1 FROM DIS_PROD_PLAN T1
		WHERE
			T1.OPEN_START_DATE > T.OPEN_START_DATE
		    AND T1.PROD_ID= #{prodId, jdbcType=VARCHAR}
		    AND T.AUTO_REDEEM_DATE!=T1.OPERATION_START_DATE
	)

SELECT DISTINCT T.SET_DATE
FROM REP_PROD_INFO T
LEFT JOIN REP_PROD_INFO T1 ON T1.P_PROD_ID=T.PROD_ID
WHERE
	1=1
  AND T1.SET_DATE = #{sysDate, jdbcType=DATE}
  AND T.PROD_ID= #{prodId, jdbcType=VARCHAR}
  AND not EXISTS(
		select * from REP_PROD_INFO t2
      	where t2.P_PROD_ID=T.PROD_ID
      	and t2.SET_DATE < #{sysDate, jdbcType=DATE}
	)

SELECT DISTINCT T.MDATE
FROM REP_PROD_INFO T
WHERE
	1=1
  AND T.MDATE = #{sysDate, jdbcType=DATE}
  AND T.PROD_ID= #{prodId, jdbcType=VARCHAR}
